import{_ as o,a0 as p,w as i,s as u,ao as r,I as a,x as s,a1 as n,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"使用時間序列數據，用開源工具助力你的邊緣項目 | LCTT x X-CMD","titleTemplate":false,"description":"使用時間序列數據，用開源工具助力你的邊緣項目 | LCTT (202301) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用時間序列數據，用開源工具助力你的邊緣項目 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用時間序列數據，用開源工具助力你的邊緣項目 | LCTT (202301) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202301/20230106.0 ⭐️⭐️ Use time-series data to power your edge projects with open source tools","title":"使用時間序列數據，用開源工具助力你的邊緣項目","tag":"202301","desc":""},"relativePath":"202301/20230106.0 ⭐️⭐️ Use time-series data to power your edge projects with open source tools.md","filePath":"[post].md"}'),d={name:"202301/20230106.0 ⭐️⭐️ Use time-series data to power your edge projects with open source tools.md"};function f(g,t,m,b,h,c){const e=p("Link");return i(),u("div",null,[t[21]||(t[21]=r('<h1 id="使用時間序列數據-用開源工具助力你的邊緣項目" tabindex="-1">使用時間序列數據，用開源工具助力你的邊緣項目 <a class="header-anchor" href="#使用時間序列數據-用開源工具助力你的邊緣項目" aria-label="Permalink to “使用時間序列數據，用開源工具助力你的邊緣項目”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202301/25/220620ftlnqfm4og7q2j0z.jpg" alt=""></p><blockquote><p>InfluxData 是一個開源的時間序列資料庫平台。下面介紹了它是如何被用於邊緣應用案例的。</p></blockquote><p>收集到的隨時間變化的數據稱為時間序列數據。今天，它已經成為每個行業和生態系統的一部分。它是不斷增長的物聯網行業的一大組成部分，將成為人們日常生活的重要部分。但時間序列數據及其需求很難處理。這是因為沒有專門為處理時間序列數據而構建的工具。在這篇文章中，我將詳細介紹這些問題，以及過去 10 年來 InfluxData 如何解決這些問題。</p><h3 id="influxdata" tabindex="-1">InfluxData <a class="header-anchor" href="#influxdata" aria-label="Permalink to “InfluxData”">​</a></h3>',5)),a("p",null,[t[1]||(t[1]=s("InfluxData 是一個開源的時間序列資料庫平台。你可能通過 ",-1)),n(e,{href:"https://opensource.com/article/17/8/influxdb-time-series-database-stack"},{default:l(()=>[...t[0]||(t[0]=[s("InfluxDB",-1)])]),_:1}),t[2]||(t[2]=s(" 瞭解該公司，但你可能不知道它專門從事時間序列資料庫開發。這很重要，因為在管理時間序列數據時，你要處理兩個問題：存儲生命週期和查詢。",-1))]),t[22]||(t[22]=r(`<p>在存儲生命週期中，開發人員通常首先收集和分析非常詳細的數據。但開發人員希望存儲較小的、降低採樣率的數據集，以描述其趨勢，而不佔用太多的存儲空間。</p><p>查詢資料庫時，你不希望基於 ID 查詢數據，而是希望基於時間範圍進行查詢。使用時間序列數據最常見的一件事是在一段時間內對其進行彙總。在典型的關係型資料庫中存儲數據時，這種查詢是很慢的，這種資料庫使用行和列來描述不同數據點的關係。專門為處理時間序列數據而設計的資料庫可以更快地處理這類查詢。InfluxDB 有自己的內置查詢語言：Flux，這是專門為查詢時間序列數據集而構建的。</p><p><img src="https://opensource.com/sites/default/files/2022-12/Telegraf.png" alt="Telegraf 如何工作的圖像"></p><h3 id="數據採集" tabindex="-1">數據採集 <a class="header-anchor" href="#數據採集" aria-label="Permalink to “數據採集”">​</a></h3><p>數據採集和數據處理都有一些很棒的工具。InfluxData 有 12 個以上的客户端庫，允許你使用自己選擇的編程語言編寫和查詢數據。這是自定義用法的一個很好的工具。開源攝取代理 Telegraf 包括 300 多個輸入和輸出插件。如果你是一個開發者，你也可以貢獻自己的插件。</p><p>InfluxDB 還可以接受上傳小體積歷史數據集的 CSV 文件，以及大數據集的批量導入。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import math</span></span>
<span class="line"><span>bicycles3 = from(bucket: &quot;smartcity&quot;)</span></span>
<span class="line"><span>    |&gt; range(start:2021-03-01T00:00:00z, stop: 2021-04-01T00:00:00z)</span></span>
<span class="line"><span>    |&gt; filter(fn: (r) =&gt; r._measurement == &quot;city_IoT&quot;)</span></span>
<span class="line"><span>    |&gt; filter(fn: (r) =&gt; r._field == &quot;counter&quot;)</span></span>
<span class="line"><span>    |&gt; filter(fn: (r) =&gt; r.source == &quot;bicycle&quot;)</span></span>
<span class="line"><span>    |&gt; filter(fn: (r) =&gt; r.neighborhood_id == &quot;3&quot;)</span></span>
<span class="line"><span>    |&gt; aggregateWindow(every: 1h, fn: mean, createEmpty:false)</span></span>
<span class="line"><span>bicycles4 = from(bucket: &quot;smartcity&quot;)</span></span>
<span class="line"><span>    |&gt; range(start:2021-03-01T00:00:00z, stop: 2021-04-01T00:00:00z)</span></span>
<span class="line"><span>    |&gt; filter(fn: (r) =&gt; r._measurement == &quot;city_IoT&quot;)</span></span>
<span class="line"><span>    |&gt; filter(fn: (r) =&gt; r._field == &quot;counter&quot;)</span></span>
<span class="line"><span>    |&gt; filter(fn: (r) =&gt; r.source == &quot;bicycle&quot;)</span></span>
<span class="line"><span>    |&gt; filter(fn: (r) =&gt; r.neighborhood_id == &quot;4&quot;)</span></span>
<span class="line"><span>    |&gt; aggregateWindow(every: 1h, fn: mean, createEmpty:false)join(tables: {neighborhood_3: bicycles3, neighborhood_4: bicycles4}, on [&quot;_time&quot;], method: &quot;inner&quot;)</span></span>
<span class="line"><span>    |&gt; keep(columns: [&quot;_time&quot;, &quot;_value_neighborhood_3&quot;,&quot;_value_neighborhood_4&quot;])</span></span>
<span class="line"><span>    |&gt; map(fn: (r) =&gt; ({</span></span>
<span class="line"><span>        r with</span></span>
<span class="line"><span>        difference_value : math.abs(x: (r._value_neighborhood_3 - r._value_neighborhood_4))</span></span>
<span class="line"><span>    }))</span></span></code></pre></div><h3 id="flux" tabindex="-1">Flux <a class="header-anchor" href="#flux" aria-label="Permalink to “Flux”">​</a></h3><p>Flux 是我們的內部查詢語言，從零開始建立，用於處理時間序列數據。它也是我們一些工具的基礎動力，包括 <ruby>任務<rt>task</rt></ruby>、<ruby>警報<rt>alert</rt></ruby> 和 <ruby>通知<rt>notification</rt></ruby>。要剖析上面的 Flux 查詢，需要定義一些東西。首先，“<ruby>桶<rt>bucket</rt></ruby>”就是我們所説的資料庫。你可以配置存儲桶，然後將數據流添加到其中。查詢會調用 <code>smartcity</code> 存儲桶，其範圍為特定的一天（準確地説是 24 小時）。你可以從存儲桶中獲取所有數據，但大多數用户都包含一個數據範圍。這是你能做的最基本的 Flux 查詢。</p><p>接下來，我添加過濾器，將數據過濾到更精確、更易於管理的地方。例如，我過濾分配給 id 為 3 的社區中的自行車數量。從那裏，我使用 <code>aggregateWindow</code> 獲取每小時的平均值。這意味着我希望收到一個包含 24 列的表，每小時一列。我也對 id 為 4 的社區進行同樣的查詢。最後，我將這兩張表相疊加，得出這兩個社區自行車使用量的差異。</p><p>如果你想知道什麼時候是交通高峯，這是不錯的選擇。顯然，這只是 Flux 查詢功能的一個小例子。但它提供了一個很好的例子，使用了 Flux 附帶的一些工具。我還有很多的數據分析和統計功能。但對於這一點，我建議查看 Flux 文檔。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import &quot;influxdata/influxdb/tasks&quot;</span></span>
<span class="line"><span>option task = {name: PB_downsample, every: 1h, offset: 10s}</span></span>
<span class="line"><span>from(bucket: &quot;plantbuddy&quot;)</span></span>
<span class="line"><span>    |&gt;range(start: tasks.lastSuccess(orTime: -task.every))</span></span>
<span class="line"><span>    |&gt;filter(fn: (r) =&gt; r[&quot;_measurement&quot;] == &quot;sensor_data&quot;)</span></span>
<span class="line"><span>    |&gt;aggregateWindow(every: 10m, fn:last, createEmpty:false)</span></span>
<span class="line"><span>    |&gt;yield(name: &quot;last&quot;)</span></span>
<span class="line"><span>    |&gt;to(bucket: &quot;downsampled&quot;)</span></span></code></pre></div><h3 id="任務" tabindex="-1">任務 <a class="header-anchor" href="#任務" aria-label="Permalink to “任務”">​</a></h3><p>InfluxDB <ruby>任務<rt>task</rt></ruby> 是一個定時 Flux 腳本，它接收輸入數據流並以某種方式修改或分析它。然後，它將修改後的數據存儲在新的存儲桶中或執行其他操作。將較小的數據集存儲到新的存儲桶中，稱為“<ruby>降採樣<rt>downsampling</rt></ruby>”，這是資料庫的核心功能，也是時間序列數據生命週期的核心部分。</p><p>你可以在當前任務示例中看到，我已經對數據進行了降採樣。我得到每 10 分鐘增量的最後一個值，並將該值存儲在降採樣桶中。原始數據集在這 10 分鐘內可能有數千個數據點，但現在降採樣桶只有 60 個新值。需要注意的一點是，我還使用了範圍內的 <code>lastSuccess</code> 函數。這會告訴 InfluxDB 從上次成功運行的時間開始運行此任務，以防它在過去 2 小時內失敗，在這種情況下，它可以追溯 3 個小時內的最後一次成功運行。這對於內置錯誤處理非常有用。</p><p><img src="https://opensource.com/sites/default/files/2022-12/TimeSeriesChecks%26Alerts.png" alt="檢查和警報通知系統的圖像"></p><h3 id="檢查和警報" tabindex="-1">檢查和警報 <a class="header-anchor" href="#檢查和警報" aria-label="Permalink to “檢查和警報”">​</a></h3><p>InfluxDB 包含一個 <ruby>警報<rt>Alert</rt></ruby> 或 <ruby>檢查<rt>Check</rt></ruby> 和 <ruby>通知<rt>notification</rt></ruby> 系統。這個系統非常簡單直白。首先進行檢查，定期查看數據以查找你定義的異常。通常，這是用閾值定義的。例如，任何低於 32°F 的温度值都被指定為“WARN”值，高於 32°F 都被分配為“OK”值，低於 0°F 都被賦予“CRITICAL”值。從那開始，你的檢查可以按你認為必要的頻率運行。你的檢查以及每個檢查的當前狀態都有歷史記錄。在不需要的時候，你不需要設置通知。你可以根據需要參考你的警報歷史記錄。</p><p>許多人選擇設置通知。為此，你需要定義一個 <ruby>通知端點<rt>notification endpoint</rt></ruby>。例如，聊天應用程序可以進行 HTTP 調用以接收通知。然後你定義何時接收通知，例如，你可以每小時運行一次檢查。你可以每 24 小時運行一次通知。你可以讓通知響應值更改，例如，“WARN”更改為“CRITICAL”，或者當值為“CRITICAL”時，無論如何都從“OK”更改為“WARN”。這是一個高度可定製的系統。從這個系統創建的 Flux 代碼也可以編輯。</p><p><img src="https://opensource.com/sites/default/files/2022-12/TimSeriesEdge.png" alt="新 Edge 功能的圖像"></p><h3 id="邊緣" tabindex="-1">邊緣 <a class="header-anchor" href="#邊緣" aria-label="Permalink to “邊緣”">​</a></h3><p>最後，我想把所有的核心功能放在一起，包括最近發佈的一個非常特別的新功能。“Edge to cloud” 是一個非常強大的工具，允許你運行開源 InfluxDB，並在出現連接問題時在本地存儲數據。連接修復後，它會將數據流傳輸到 InfluxData 雲平台。</p><p>這對於邊緣設備和重要數據非常重要，因為任何數據丟失都是有害的。你定義一個要複製到雲的存儲桶，然後該存儲桶有一個磁盤支持的隊列來本地存儲數據。然後定義雲存儲桶應該複製到的內容。在連接到雲端之前，數據都存儲在本地。</p><h3 id="influxdb-和物聯網邊緣" tabindex="-1">InfluxDB 和物聯網邊緣 <a class="header-anchor" href="#influxdb-和物聯網邊緣" aria-label="Permalink to “InfluxDB 和物聯網邊緣”">​</a></h3>`,24)),a("p",null,[t[4]||(t[4]=s("假設你有一個項目，你想使用連接到植物上的物聯網傳感器 ",-1)),n(e,{href:"https://opensource.com/article/22/5/plant-care"},{default:l(()=>[...t[3]||(t[3]=[s("監測家裏植物的健康狀況",-1)])]),_:1}),t[5]||(t[5]=s("。該項目是使用你的筆記本電腦作為邊緣設備設置的。當你的筆記本電腦合上或關閉時，它會在本地存儲數據，然後在重新連接時將數據流傳到我的雲存儲桶。",-1))]),t[23]||(t[23]=a("p",null,[a("img",{src:"https://opensource.com/sites/default/files/2022-12/TimeSeriesplantbuddy.png",alt:"圖片展示了 Plant buddy 的工作方式"})],-1)),t[24]||(t[24]=a("p",null,"需要注意的一點是，在將數據存儲到複製桶之前，這會對本地設備上的數據進行降採樣。你的植物傳感器每秒提供一個數據點。但它將數據壓縮為一分鐘的平均數，因此存儲的數據更少了。在雲賬户中，你可以添加一些警報和通知，讓你知道植物的水分何時低於某個水平，需要澆水。也可以在網站上使用視覺效果來告訴用户植物的健康狀況。",-1)),t[25]||(t[25]=a("p",null,"資料庫是許多應用程序的主幹。在像 InfluxDB 的時間序列資料庫平台中使用帶有時間戳的數據可以節省開發人員的時間，並使他們能夠訪問各種工具和服務。InfluxDB 的維護者喜歡看到人們在我們的開源社區中構建什麼，所以請與我們聯繫，並與其他人共享你的項目和代碼！",-1)),t[26]||(t[26]=a("hr",null,null,-1)),a("p",null,[t[7]||(t[7]=s("via: ",-1)),n(e,{href:"https://opensource.com/article/23/1/time-series-data-edge-open-source-tools"},{default:l(()=>[...t[6]||(t[6]=[s("https://opensource.com/article/23/1/time-series-data-edge-open-source-tools",-1)])]),_:1})]),a("p",null,[t[12]||(t[12]=s("作者：",-1)),n(e,{href:"https://opensource.com/users/zoesteinkamp"},{default:l(()=>[...t[8]||(t[8]=[s("Zoe Steinkamp",-1)])]),_:1}),t[13]||(t[13]=s(" 選題：",-1)),n(e,{href:"https://github.com/lkxed"},{default:l(()=>[...t[9]||(t[9]=[s("lkxed",-1)])]),_:1}),t[14]||(t[14]=s(" 譯者：",-1)),n(e,{href:"https://github.com/ZhangZhanhaoxiang"},{default:l(()=>[...t[10]||(t[10]=[s("ZhangZhanhaoxiang",-1)])]),_:1}),t[15]||(t[15]=s(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:l(()=>[...t[11]||(t[11]=[s("wxy",-1)])]),_:1})]),a("p",null,[t[18]||(t[18]=s("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[16]||(t[16]=[s("LCTT",-1)])]),_:1}),t[19]||(t[19]=s(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:l(()=>[...t[17]||(t[17]=[s("Linux中國",-1)])]),_:1}),t[20]||(t[20]=s(" 榮譽推出",-1))])])}const T=o(d,[["render",f]]);export{k as __pageData,T as default};
